int a = INT_MAX;
int b = a + 1; // Signed integer overflow: UB
// Compiler assumes a+1 > a, enabling loop optimizations.

int arr[5];
int i = 5;
arr[i] = 42; // Out-of-bounds access: UB
// Optimizers assume this access is valid for alias analysis.

char* p = nullptr;
char c = *p; // Dereferencing null pointer: UB
// If (p != nullptr) check precedes, the compiler might remove it.

unsigned int val = 1;
val = val << 32; // Shift amount >= bit width: UB (32-bit int)
// If val < 32 check is present, it might be ignored.

if (x > x+1) { /* unreachable code */ }
// Comparison involving signed overflow results in UB,
// allowing the compiler to assume 'false'.

void infinite_loop() {
    for (;;) {}
}
// Function containing only UB: Compiler may assume it never returns,
// optimizing away code paths that depend on its return.
